// Damping Sphere
// status: planned
// requires: spell cost rule with terms
// If a land is tapped for two or more mana, it produces {C} instead of any other type and amount.
// Each spell a player casts costs {1} more to cast for each other spell that player has cast this turn.
#[allow(unused_imports)] use cantrip_api::*;
#[allow(unused_variables)] fn ability_0_applies(q: &dyn Query, asker: &Asker, proposal: &Proposal) -> bool { if let Proposal::ManaProduction(m) = proposal { let id = m.permanent; let amount = m.total(); let subject = Target::Object(id); let data = [amount, u32::MAX]; if q.chars(id).is(CardType::Land) && (i64::from(amount)) >= (2i64) { return true; } }
 false }
#[allow(unused_variables, unused_mut)] fn ability_0_apply(q: &dyn Query, asker: &Asker, proposal: &mut Proposal) { let seen = *proposal; if let Proposal::ManaProduction(seen) = &seen { let m = seen; let id = m.permanent; let amount = m.total(); let subject = Target::Object(id); let data = [amount, u32::MAX]; if let Proposal::ManaProduction(m) = proposal { m.mana = ManaPool::default(); m.mana.0[Mana::C as usize] = (1i64).max(0) as u32; } } }
#[allow(unused_variables)] fn ability_1_0_applies(q: &dyn Query, asker: &Asker, player: PlayerId) -> bool { true }
